// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface CoinToken {
    function owner() external view returns (address);
    function mint(address account, uint256 amount) external;
    function balanceOf(address account) external view returns (uint256);
    function decimals() external view returns (uint256);
    function paused() external view returns (bool);
    function unpause() external;
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xF44DE2b8731cD69d4A727Da0214874aE35559426;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll interact directly with the deployed contract
        // The test framework already provides TARGET and attacker variables
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the current owner
        address currentOwner = CoinToken(TARGET).owner();
        console.log("Current owner:", currentOwner);
        require(currentOwner != address(0), "Owner is zero address");

        // Check if contract is paused
        bool isPaused = CoinToken(TARGET).paused();
        console.log("Contract paused:", isPaused);

        // If paused, unpause it as owner
        if (isPaused) {
            console.log("Unpausing contract...");
            vm.prank(currentOwner);
            CoinToken(TARGET).unpause();
            console.log("Contract unpaused");
        }

        // Get decimals
        uint256 decimals = CoinToken(TARGET).decimals();
        console.log("Decimals:", decimals);

        // Store initial balance
        uint256 initialBalance = CoinToken(TARGET).balanceOf(attacker);
        console.log("Initial balance:", initialBalance);

        // Mint a reasonable amount - start with 1000 tokens
        uint256 mintAmount = 1000 * (10 ** decimals);
        console.log("Minting amount:", mintAmount);

        // Impersonate owner and mint
        vm.prank(currentOwner);
        CoinToken(TARGET).mint(attacker, mintAmount);
        console.log("Mint transaction completed");

        // Get new balance
        uint256 newBalance = CoinToken(TARGET).balanceOf(attacker);
        console.log("New balance:", newBalance);

        // Verify balance increased
        assertGt(newBalance, initialBalance, "Balance should have increased after minting");

        // Calculate expected minimum increase (account for potential fees)
        uint256 expectedMinIncrease = mintAmount * 99 / 100; // Allow 1% for potential fees
        assertGt(newBalance - initialBalance, expectedMinIncrease, "Should have received most of minted tokens");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
